from urllib.request import urlopen
import shlex
import subprocess
def dispatch(words):
    subprocess.run(words)
def choose(i):
    if i == 0:
        parts = []
        parts.extend(shlex.split(urlopen('https://example.invalid/').read().decode()))
        return parts
    if i == 1:
        return [urlopen('https://example.invalid/1').read().decode()]
    if i == 2:
        return [urlopen('https://example.invalid/2').read().decode()]
    if i == 3:
        return [urlopen('https://example.invalid/3').read().decode()]
    if i == 4:
        return [urlopen('https://example.invalid/4').read().decode()]
    if i == 5:
        return [urlopen('https://example.invalid/5').read().decode()]
    if i == 6:
        return [urlopen('https://example.invalid/6').read().decode()]
    return ['example']
def show(i):
    output = ['example', '--']
    output.extend(choose(i))
    dispatch(output)

